      4: { title: 'Chapter 4 • Marketing & Disciplinary Framework', slug: 'Ch4_Marketing_Publicity_Disciplinary' },
      5: { title: 'Chapter 5 • Risk Management (AFM)', slug: 'Ch5_Risk_Management_AFM' },
